def deep_merge(base, override):
    """Return a NEW dict: base merged with override. Nested dicts merge recursively; any other value in override replaces
    the base value (lists are replaced, not concatenated). A value of None in override REMOVES that key from the result.
    Neither input is modified and the result shares no mutable containers with either input."""
    result = {}
    # First, populate result with a deep copy of base, ensuring no shared mutable containers
    for k, v in base.items():
        if isinstance(v, dict):
            result[k] = dict(v)  # Copy nested dicts
        elif isinstance(v, (list, set)):
            result[k] = v[:]  # Copy lists/sets
        else:
            result[k] = v  # Copy other values (immutable or shallow copy of reference)

    # Then, merge override into result
    for k, v_override in override.items():
        if v_override is None:
            # If override value is None, remove the key from the result
            if k in result:
                del result[k]
        elif k in result and isinstance(result[k], dict) and isinstance(v_override, dict):
            # If both base and override have dicts for this key, merge recursively
            result[k] = deep_merge(result[k], v_override)
        else:
            # For non-dict values, or if types don't match for recursive merge, replace the value.
            # Ensure mutable containers from override are also copied.
            if isinstance(v_override, dict):
                result[k] = dict(v_override)
            elif isinstance(v_override, (list, set)):
                result[k] = v_override[:]
            else:
                result[k] = v_override
    return result
