def parse_value(text):
    """Convert an environment string: "true"/"yes"/"on"/"1" (any case, surrounding spaces ignored) -> True,
    "false"/"no"/"off"/"0" -> False, a decimal integer like "42" or "-7" -> int, a decimal number like "2.5" -> float,
    "" or "null"/"none" (any case) -> None, anything else -> the stripped string unchanged. Note "1" and "0" are booleans."""
    s = text.strip().lower()

    if s in ("true", "yes", "on", "1"):
        return True
    if s in ("false", "no", "off", "0"):
        return False
    if s in ("", "null", "none"):
        return None

    try:
        return int(s)
    except ValueError:
        pass  # Not an integer, try float

    try:
        return float(s)
    except ValueError:
        pass  # Not a float, return as string

    return text.strip()  # Return the original stripped string if no other type matches
